.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-desktop) !important}
@media(max-width: 976px) {.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-tablet) !important}}
@media(max-width: 767px) {.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-mobile) !important}}
.eon8-live-page .uk-navbar-left img {
    height: 60px;
    width: auto;
    object-fit: contain;
    transition: height 0.35s ease;
    display: block;
    margin-top:-10px;
}
.eon8-live-page .uk-navbar {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    position: relative;
    z-index: 1;
}
.eon8-live-page .uk-navbar-left {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 80px !important;
    flex-wrap: nowrap;
}
.eon8-live-page .uk-navbar-right {
    display: flex !important;
    align-items: center;
    margin-left: auto;
}
.eon8-live-page .uk-navbar-nav > li > .uk-navbar-dropdown {
    left: 50% !important;
    transform: translateX(-50%) !important;
    right: auto !important;
}
.eon8-live-page .uk-navbar-nav {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 5px;
    list-style: none;
    margin: 0;
    padding: 0;
}
.eon8-live-page .uk-navbar-nav > li {
    display: flex;
    align-items: center;
    position: relative;
    white-space: nowrap;
}
.eon8-live-page .uk-navbar-nav > li > a {
    display: flex;
    align-items: center;
    padding: 6px 10px;
    font-size: 14px;
    line-height: 1;
    text-decoration: none;
    position: relative;
}
.eon8-live-page .uk-navbar-nav > li > a::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 10px;
    right: 10px;
    height: 2px;
    transform: scaleX(0);
    transition: transform 0.3s ease;
    transform-origin: left;
}
.eon8-live-page .uk-navbar-nav > li > a:hover::after {
    transform: scaleX(1);
}
@media (max-width: 1024px) {.eon8-live-page .uk-navbar-left img {
        height: 50px;
    }
.eon8-live-page .uk-navbar-nav {
        gap: 5px;
    }}
@media (max-width: 768px) {.eon8-live-page .uk-navbar-left img {
        height: 45px;
    }
.eon8-live-page .uk-navbar-nav {
        display: none !important;
    }}
@media (max-width: 480px) {.eon8-live-page .uk-navbar-left img {
        height: 38px;
    }}
.eon8-live-page #nft-client-slider .logo-slider .slide {
    width: 200px;
    transform: rotate(0deg);
    -webkit-transform: rotate(0deg);
}
.eon8-live-page .reverse-slide .logo-slide-track {
    animation-direction: reverse
}
@media (max-width: 767px) {.eon8-live-page #nft-client-slider.slider {
        display: block;
        padding: 0;
    }
.eon8-live-page #nft-client-slider h1 {
        font-size: 2.5rem;
        padding-top: 60px;
    }}
.eon8-live-page section {position: relative;width: 100%;padding: 0;}
.eon8-live-page .bannerpart {
    background: url("/wp-content/uploads/2023/01/communitymarketingbanner.png")no-repeat;
    width: 100%;

    background-position: center;
    background-size: cover;
}
.eon8-live-page ul.leftside, .eon8-live-page ul.rightside {
    position: relative;
    width: 50%;
    float: left;
    list-style-type: disclosure-closed;
}
.eon8-live-page .page-template.page-template-community-marketing-agency #responsive-form {
    max-width: 100%;
    margin: 0 auto;
    width: 100%;
    padding: 20px;
    border: 1px solid #173BC1;
    border-radius: 7px;
    background: #173BC1;
    box-shadow: 0 0 10px #f9f9f9;
}
.eon8-live-page ul.leftside li, .eon8-live-page ul.rightside li {
    padding: 3% 0;
}
.eon8-live-page .wpcf7 textarea {max-height: 120px;}
.eon8-live-page .values {
    background: url("/wp-content/uploads/2023/01/parallax-counter.jpg")no-repeat;
    width: 100%;
    background-position: center;
    background-size: cover;
    overflow: hidden;
    position: relative;
}
.eon8-live-page .parallax-counter {
    width: 100%;
    float: left;
}
.eon8-live-page .parallax-counter:before {
    content: "";
    position: absolute;
    width: 140%;
    height: 140%;
    opacity: 0.9;
    background-image: linear-gradient(127deg, #2973D7 0%, #26ACB9 91%);
    z-index: 0;
    top: 0%;
    left: 0%;
}
.eon8-live-page .parallax-counter .parallax-content .count-item {
    height: 250px;
    position: relative;
    float: left;
    width: 100%;
}
.eon8-live-page .parallax-counter .parallax-content .count-item strong {
    display: block;
    text-align: center;
    font-weight: 400;
    font-size: 40px;
    letter-spacing: 1.72px;
    margin-bottom: 10px;
    color: #fff;
    margin-top: 40px;
    -webkit-transition: all 0.3s ease 0s;
    -moz-transition: all 0.3s ease 0s;
    -o-transition: all 0.3s ease 0s;
    transition: all 0.3s ease 0s;
}
.eon8-live-page .parallax-counter .parallax-content .count-item span {
    display: block;
    text-align: center;
    color: #fff;
    font-weight: 400;
    font-size: 20px;
    letter-spacing: 0.86px;
}
.eon8-live-page .parallax-counter .parallax-content .count-item.elliptical-bottom:after {
    content: "";
    position: absolute;
    width: 118px;
    height: 17px;
    top: 70px;
    left: 83%;
    background: url("/wp-content/uploads/2023/01/elliptical-bottom.png") center center no-repeat;
    -webkit-transition: all 0.3s ease 0s;
    -moz-transition: all 0.3s ease 0s;
    -o-transition: all 0.3s ease 0s;
    transition: all 0.3s ease 0s;
}
.eon8-live-page .parallax-counter .parallax-content .count-item.elliptical-top:after {
    content: "";
    position: absolute;
    width: 118px;
    height: 17px;
    top: 60px;
    left: 83%;
    background: url("/wp-content/uploads/2023/01/elliptical-top.png") center center no-repeat;
    -webkit-transition: all 0.3s ease 0s;
    -moz-transition: all 0.3s ease 0s;
    -o-transition: all 0.3s ease 0s;
    transition: all 0.3s ease 0s;
}
.eon8-live-page section.secondpart {
    padding: 7% 0 6%;
}
.eon8-live-page .client_sliderr .logo-slider .slide {
    width: 200px;
    transform: rotate(0deg);
    -webkit-transform: rotate(0deg);
}
.eon8-live-page .reverse-slide .logo-slide-track {
    animation-direction: reverse
}
.eon8-live-page .client_slider .logo-slider .slide {
    width: 102px;
    height: 87px;
    padding: 20px;
    transform: rotate(-4deg);
    -webkit-transform: rotate(360deg);
}
@media only screen and (max-width: 767px) {.eon8-live-page .parallax-counter .parallax-content .count-item.elliptical-top:after, .eon8-live-page .parallax-counter .parallax-content .count-item.elliptical-bottom:after {background: none;}
.eon8-live-page .values {height: 700px;padding: 10% 0 0;}
.eon8-live-page .parallax-counter .parallax-content .count-item {height: 140px;}
.eon8-live-page .client_sliderr.slider { display: block; padding: 0;}
.eon8-live-page .client_sliderr h1 { font-size: 2.5rem;padding-top: 60px;}}
